# TIENG HAN MR LEE | VERSION 2026.10 | SAFE ONE-FILE UPGRADER
# Windows PowerShell 5.1 / UTF-8 BOM. Run from the actual website folder.
param([string]$WebsitePath = '')
$ErrorActionPreference='Stop'
if([string]::IsNullOrWhiteSpace($WebsitePath)) { $WebsitePath = Split-Path -Parent $MyInvocation.MyCommand.Path }
$WebsitePath=[System.IO.Path]::GetFullPath($WebsitePath)
$Utf8 = New-Object System.Text.UTF8Encoding($false)
$backupDir=Join-Path (Split-Path -Parent $WebsitePath) ('.mrlee-backup-engagement-'+(Get-Date -Format 'yyyyMMdd-HHmmss'))
function Read-File([string]$relative){ return [System.IO.File]::ReadAllText((Join-Path $WebsitePath $relative),$Utf8) }
function Save-File([string]$relative,[string]$newText){
 $dest=Join-Path $WebsitePath $relative
 $old=if(Test-Path $dest){[System.IO.File]::ReadAllText($dest,$Utf8)}else{''}
 if((Test-Path $dest) -and $old -ceq $newText) {return}
 if(Test-Path $dest){
   $backup=Join-Path $backupDir $relative
   $folder=Split-Path -Parent $backup
   [System.IO.Directory]::CreateDirectory($folder)|Out-Null
   [System.IO.File]::Copy($dest,$backup,$true)
 }
 $parent=Split-Path -Parent $dest
 [System.IO.Directory]::CreateDirectory($parent)|Out-Null
 [System.IO.File]::WriteAllText($dest,$newText,$Utf8)
 Write-Host ('UPDATED: '+$relative)
}
function Unpack([string]$code){
 $bytes=[Convert]::FromBase64String(($code -replace '\s',''))
 $mem=[System.IO.MemoryStream]::new($bytes)
 $stream=[System.IO.Compression.GzipStream]::new($mem,[System.IO.Compression.CompressionMode]::Decompress)
 $output=[System.IO.MemoryStream]::new()
 try{$stream.CopyTo($output);return [System.Text.Encoding]::UTF8.GetString($output.ToArray())}
 finally{$output.Dispose();$stream.Dispose();$mem.Dispose()}
}
function Ensure-Boot([string]$html){
 $html=[regex]::Replace($html,'(?is)<script\b[^>]*src="mrlee-daily-boot\.js[^"]*"[^>]*>\s*</script>','')
 if($html -notmatch 'mrlee-engagement[.]css'){
   $html=[regex]::Replace($html,'(?i)</head>','<link rel="stylesheet" href="mrlee-engagement.css?v=20261010" />'+"`n"+'</head>',1)
 }
 if($html -notmatch 'mrlee-engagement[.]js'){
   $html=[regex]::Replace($html,'(?i)</body>','<script type="module" src="mrlee-engagement.js?v=20261010"></script>'+"`n"+'</body>',1)
 }
 return $html
}
# Preflight! Never start writing if user page shapes cannot be safely patched.
foreach($name in @('index.html','bai-hoc.html','giao-tiep-theo-chu-de.html','firebase-config.js')){
 if(-not (Test-Path (Join-Path $WebsitePath $name))){throw ('Missing '+$name+' in '+$WebsitePath+'. Move this installer into your project ROOT.')}
}
$conv=Read-File 'giao-tiep-theo-chu-de.html'
if($conv -notmatch 'MRLEE-DEEP-TOPICS-V20261010'){
 if($conv -notmatch 'const\s+ALL\s*=\s*TOPICS\s*\.\s*flatMap' -or $conv -notmatch 'const\s+TOPICS\s*='){
   throw 'The conversation HTML has a different data shape. No file was changed. Please provide giao-tiep-theo-chu-de.html.'
 }
 if(-not $conv.Contains("(st.topic==='all'||x.topic===st.topic)")){
   throw 'Cannot locate topic filter. No files changed. Please provide the current conversation page.'
 }
}
# The speaking engine must be the level-1–6 version or missing (auto-installed).
$enginePath=Join-Path $WebsitePath 'mrlee-speaking-app.js'
if((Test-Path $enginePath) -and ((Read-File 'mrlee-speaking-app.js') -notmatch 'ADVANCED_SPEAKING_BANK|DEEP_SPEAKING_BANK')){
 throw 'Speaking app does not support the level-1–6 bank. No files were changed; send mrlee-speaking-app.js for a compatible patch.'
}
$lesson=Read-File 'bai-hoc.html'
if($lesson -notmatch 'MRLEE-SIX-LEVEL-HUB' -and $lesson -notmatch '(?i)<main\b[^>]*>'){
 throw 'bai-hoc.html has no main tag. No file was changed.'
}
Write-Host 'Compatibility preflight passed. Creating a backup OUTSIDE the Git repository.'

