2cDUTgdTmwtTOxnmSu+xaD3o5TsC6nDgQFUP9vnZoC2eDm1xLtriDNoVaMox1mte72toy96+5cHsEZMmhNgBKTsbpPrpkOpzkeon
I03HaEOUlQmsh48O98QYP3zU7/5fQwnVlmE2HzuiB/8qANo4Lc02YZiFFHORHHgzC9Ls5Op/3fvoW7Q+7SvdRAM46WLq7ad7LF1K
wjnsuGcfD1bUKEYYt/sR2vJSQnPPbKclfjpeZdyjaPP1a1deQ5aXmgNx976VrpkhEoA3+JsAj+IteHXjEp73Jizef/8GLj6BIigP
AAA=
'@

# Home nameplate; preserve slides/carousel, image cover and all navigation.
$home=Read-File 'index.html'
$home=Ensure-Boot $home
if($home -notmatch 'id="mrleeStudentPanel"'){
 $panel='<section id="mrleeStudentPanel" class="mrlee-student-panel" aria-label="Bảng tên, điểm và chuỗi ngày học" hidden></section>' + "`n"
 $m=[regex]::Match($home,'(?i)<section\b[^>]*class="hero\b[^"]*"[^>]*>')
 if(-not $m.Success){$m=[regex]::Match($home,'(?i)</header>')}
 if(-not $m.Success){throw 'Cannot identify the home hero/header.'}
 $pos=if($m.Value -match '(?i)</header>'){$m.Index+$m.Length}else{$m.Index}
 $home=$home.Substring(0,$pos)+$panel+$home.Substring($pos)
}
$home=[regex]::Replace($home,'(?is)(<h3>\s*Bài học tiếng Hàn\s*</h3>\s*<p>)[^<]*(</p>)', '${1}Học theo lộ trình cấp 1–6, có bài luyện nói và tích điểm theo tiến độ.${2}',1)
Save-File 'index.html' $home

# Lesson hub: keep original lesson menu/content, add level switch above it.
# The speaking engine must be the level-1–6 version or missing (auto-installed).
$enginePath=Join-Path $WebsitePath 'mrlee-speaking-app.js'
if((Test-Path $enginePath) -and ((Read-File 'mrlee-speaking-app.js') -notmatch 'ADVANCED_SPEAKING_BANK|DEEP_SPEAKING_BANK')){
 throw 'Speaking app does not support the level-1–6 bank. No files were changed; send mrlee-speaking-app.js for a compatible patch.'
}
$lesson=Read-File 'bai-hoc.html'
if($lesson -notmatch 'MRLEE-SIX-LEVEL-HUB'){
 $m=[regex]::Match($lesson,'(?i)<main\b[^>]*>')
 $pos=$m.Index+$m.Length
 $lesson=$lesson.Substring(0,$pos)+$HubFragment+$lesson.Substring($pos)
}
$lesson=Ensure-Boot $lesson
Save-File 'bai-hoc.html' $lesson

# Advanced conversations: extend TOPICS (do not overwrite old questions or local favourites).
$conv=Read-File 'giao-tiep-theo-chu-de.html'
if($conv -notmatch 'MRLEE-DEEP-TOPICS-V20261010'){
 $addHead=@'
<script src="mrlee-deep-topics.js?v=20261010"></script>
<script defer src="mrlee-deep-ui.js?v=20261010"></script>
<style id="mrleeDeepStyles">.controls{grid-template-columns:minmax(0,1fr) minmax(130px,160px) 160px auto}.mrlee-situation{font-size:11px;color:#7c5b37;background:#fff5e7;border-radius:7px;padding:5px 8px;margin:8px 0 0}.mrlee-deep-practice{display:inline-flex;text-decoration:none;align-items:center;justify-content:center}@media(max-width:760px){.controls{grid-template-columns:1fr 1fr}.controls input{grid-column:1/-1}}</style>
'@
 $conv=[regex]::Replace($conv,'(?i)</head>',($addHead+"`n"+'</head>'),1)
 $conv=[regex]::Replace($conv,'(const\s+ALL\s*=\s*TOPICS\s*\.\s*flatMap)',('/* MRLEE-DEEP-TOPICS-V20261010 */'+"`n"+'TOPICS.push(...(window.MRLEE_DEEP_TOPICS || []));'+"`n"+'$1'),1)
 if($conv -notmatch 'level:\(x.level\|\|t.level\|\|2\)'){
    $conv=$conv.Replace('...x,topic:t.id,topicTitle:t.title','...x,topic:t.id,topicTitle:t.title,level:(x.level||t.level||2)')
 }
 if($conv -notmatch 'id="mrleeLevelFilter"'){
    $selector='<select id="mrleeLevelFilter" aria-label="Lọc mẫu câu theo cấp độ"><option value="all">📚 Tất cả trình độ</option><option value="2">Cấp 1–2</option><option value="3">Cấp 3</option><option value="4">Cấp 4</option><option value="5">Cấp 5</option><option value="6">Cấp 6</option></select>'
    $conv=$conv.Replace('<select id="rateSelect"',($selector+'<select id="rateSelect"'))
 }
 $needle="(st.topic==='all'||x.topic===st.topic)"
 $selectorCode="(st.topic==='all'||x.topic===st.topic)&&(e('mrleeLevelFilter').value==='all'||(e('mrleeLevelFilter').value==='2'?Number(x.level)<=2:String(x.level)===e('mrleeLevelFilter').value))"
 $conv=$conv.Replace($needle,$selectorCode)
 $last=$conv.LastIndexOf('renderAll();')
 if($last -lt 0){throw 'Conversation page has no final renderAll.'}
 $listen="e('mrleeLevelFilter').addEventListener('change',()=>{st.topic='all';st.limit=24;renderAll()});"+"`n"
 $conv=$conv.Substring(0,$last)+$listen+$conv.Substring($last)
}
$conv=Ensure-Boot $conv
Save-File 'giao-tiep-theo-chu-de.html' $conv

# Deep speaking bank: add to existing speaking app and topic link gate.
$js=Read-File 'mrlee-speaking-app.js'
if($js -notmatch 'mrlee-speaking-deep[.]js'){
 $js=$js.Replace("import { ADVANCED_SPEAKING_BANK } from './mrlee-speaking-advanced.js';", "import { ADVANCED_SPEAKING_BANK } from './mrlee-speaking-advanced.js';"+"`n"+"import { DEEP_SPEAKING_BANK } from './mrlee-speaking-deep.js';")
 $js=$js.Replace('[...SPEAKING_BANK,...ADVANCED_SPEAKING_BANK]','[...SPEAKING_BANK,...ADVANCED_SPEAKING_BANK,...DEEP_SPEAKING_BANK]')
 if($js -notmatch 'DEEP_SPEAKING_BANK'){throw 'Cannot patch speaking catalogue; no file replaced.'}
 Save-File 'mrlee-speaking-app.js' $js
}
$gate=Read-File 'mrlee-points-gate.js'
if($gate -notmatch 'mrlee-speaking-deep[.]js'){
 $gate=$gate.Replace("import { SPEAKING_BANK } from './mrlee-speaking-bank.js';", "import { SPEAKING_BANK } from './mrlee-speaking-bank.js';"+"`n"+"import { DEEP_SPEAKING_BANK } from './mrlee-speaking-deep.js';")
 $gate=$gate.Replace("const topicTasks=SPEAKING_BANK.filter(t=>t.kind==='topic');", "const topicTasks=[...SPEAKING_BANK,...DEEP_SPEAKING_BANK].filter(t=>t.kind==='topic');")
 if($gate -match 'DEEP_SPEAKING_BANK'){Save-File 'mrlee-points-gate.js' $gate}
}

# On already-installed pages, replace the old corner reward notification with centered welcome.
foreach($file in @('dang-nhap.html','so-cap-1.html','so-cap-2.html','lo-trinh-1-6.html','luyen-noi-tinh-diem.html','on-luyen-phong-van.html','kiem-tra-online.html','kiem-tra-dau-vao.html','lich-su-hoc-tap.html','de-thi-topik.html','bo-sach.html')){
 $path=Join-Path $WebsitePath $file
 if(Test-Path $path){ Save-File $file (Ensure-Boot (Read-File $file)) }
}
Write-Host 'SUCCESS: Student name + points / centered daily welcome / level 1-6 lesson hub / 240 advanced phrases / 12 speaking tasks.' -ForegroundColor Green
Write-Host ('BACKUP: '+$backupDir)
Write-Host 'Next: Test with Live Server, then git add and push. No Firestore rules changes were introduced by this addon.'
